'use strict';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({arrived:true,count:false,labels:[false,false],seals:[null,null,null],photos:[null,null],cmrLabel:false,pages:[],allPages:false,finished:false,discrepancy:null});
const state={operation:'load',screen:'arrival',language:'en',manualLanguage:false,operations:{load:fresh(),unload:fresh()},modal:null,anchor:'place'};
const dictionary={pl:{pickup:'ZAŁADUNEK',delivery:'ROZŁADUNEK',flag:'🇵🇱'},en:{pickup:'PICKUP',delivery:'DELIVERY',flag:'🇬🇧'},de:{pickup:'BELADUNG',delivery:'ENTLADUNG',flag:'🇩🇪'},it:{pickup:'CARICO',delivery:'SCARICO',flag:'🇮🇹'}};
const current=()=>state.operations[state.operation];
const isLoad=()=>state.operation==='load';
const name=()=>isLoad()?'Załadunek':'Rozładunek';
const genitive=()=>isLoad()?'załadunku':'rozładunku';
const foreign=()=>dictionary[state.language][isLoad()?'pickup':'delivery'];
const place=()=>isLoad()?{company:'ID Logistics Tilburg B.V.',street:'Hermesstraat 1',city:'5047 TS Tilburg, Holandia',gate:'B',parking:'P2',warehouse:'4',ramp:'04',contact:'Thomas de Vries',phone:'+31 00 000 0000'}:{company:'LogiPark Poznań',street:'ul. Magazynowa 18',city:'62-023 Gądki, Polska',gate:'A',parking:'P1',warehouse:'3',ramp:'12',contact:'Anna Kowalska',phone:'+48 000 000 000'};
const anchors=['count','cargo-label','cargo-qr','photos','cmr-label','final'];
const stepNames=['Liczba sztuk ładunku','Etykiety na ładunku','QR etykiet ładunku','Dwa zdjęcia ładunku','Etykieta i QR dokumentu CMR','Pełny skan CMR i finalizacja'];
let uploadTarget=null,toastTimer,focusBeforeModal;
function completed(){const s=current();return[s.count,s.count&&s.labels.every(Boolean),s.count&&s.labels.every(Boolean)&&s.seals.slice(0,2).every(Boolean),s.count&&s.labels.every(Boolean)&&s.seals.slice(0,2).every(Boolean)&&s.photos.every(Boolean),s.count&&s.labels.every(Boolean)&&s.seals.slice(0,2).every(Boolean)&&s.photos.every(Boolean)&&s.cmrLabel&&Boolean(s.seals[2]),s.count&&s.labels.every(Boolean)&&s.seals.every(Boolean)&&s.photos.every(Boolean)&&s.cmrLabel&&s.pages.length>0&&s.allPages];}
const readyToFinalize=()=>completed().slice(0,5).every(Boolean);
const nextStep=()=>{const i=completed().findIndex(x=>!x);return i<0?5:i;};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function revoke(item){if(item?.url?.startsWith('blob:'))URL.revokeObjectURL(item.url);}
function clearAfter(index){const s=current();if(index<2){s.photos.forEach(revoke);s.photos=[null,null];}if(index<4){s.cmrLabel=false;s.seals[2]=null;}s.pages.forEach(revoke);s.pages=[];s.allPages=false;s.finished=false;}
function go(screen){
  if(screen==='finalization'&&!readyToFinalize()){toast('Najpierw wykonaj kroki 1–5. Pełny skan CMR dodasz przy finalizacji.');return;}
  closeModal(false);state.screen=screen;
  if(screen==='arrival')current().arrived=true;
  if(screen==='travel')current().arrived=false;
  state.anchor='place';render();$('#app-scroll').scrollTop=0;
}
function scrollToSection(id){
  if(state.screen!=='arrival'){state.screen='arrival';current().arrived=true;render();}
  const target=$(`#section-${id}`);if(!target)return;
  state.anchor=id;updateSidebar();target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});
}
function languageControl(){return `<label class="language-control"><span aria-hidden="true">${dictionary[state.language].flag}</span><select id="language-select" aria-label="Język nazw operacji transportowych">${['pl','en','de','it'].map(l=>`<option value="${l}" ${l===state.language?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select></label>`;}
function mapsLink(navigate=false){const p=place();return navigate?`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.street+', '+p.city)}&travelmode=driving`:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.company+', '+p.street+', '+p.city)}`;}
function heading(travel=false){return `<div class="operation-heading"><div><div class="overline">SS/26/105/H · PUNKT ${isLoad()?'1':'2'}/2</div><h2>${name()} <small>${foreign()}</small></h2></div><div class="header-tools"><a class="tool-button" href="${mapsLink()}" target="_blank" rel="noopener" aria-label="Otwórz lokalizację na mapie" title="Mapa">${icon('pin')}</a><a class="tool-button" href="${mapsLink(true)}" target="_blank" rel="noopener" aria-label="Uruchom nawigację do punktu" title="Nawigacja">${icon('nav')}</a>${languageControl()}</div></div><div class="heading-status"><span class="badge ${travel?'orange':'green'}">${icon(travel?'route':'check')}${travel?'W drodze':'Jesteś na miejscu'}</span><span class="arrival-time">${icon('clock')}${travel?'Okno 10:00–12:00':'Przyjazd 10:42'}</span></div>`;}
function yardPlan(){const p=place();return `<svg viewBox="0 0 340 112" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Poglądowy plan terenu: brama ${p.gate}, parking ${p.parking}, magazyn ${p.warehouse}, rampa ${p.ramp}"><rect width="340" height="112" fill="#f7f8f5"/><path d="M15 93H322V16H15Z" fill="none" stroke="#dde3d5" stroke-dasharray="4 3"/><rect x="202" y="24" width="111" height="62" rx="5" fill="#e9ede4" stroke="#d5ddca"/><rect x="109" y="22" width="68" height="33" rx="5" fill="#edf1e8" stroke="#dbe3d1"/><g fill="#7f8d72" font-family="Manrope,Arial" font-size="9"><text x="123" y="42">Parking ${p.parking}</text><text x="217" y="44">Magazyn ${p.warehouse}</text><text x="22" y="105">Brama ${p.gate}</text></g><path d="M44 94V71H143V58M143 71h64V61" fill="none" stroke="#ff6a1a" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="m139 62 4-6 4 6M203 66l4-6 4 6" fill="none" stroke="#ff6a1a" stroke-width="2"/><circle cx="44" cy="94" r="5" fill="#ff6a1a" stroke="white" stroke-width="2"/><rect x="198" y="49" width="22" height="22" rx="5" fill="#ff6a1a"/><text x="209" y="64" text-anchor="middle" font-family="Arial" font-size="10" font-weight="bold" fill="#3c2e20">${p.ramp}</text><text x="230" y="70" font-family="Manrope,Arial" font-size="9" fill="#8a9380">Rampa</text></svg>`;}
function placePanel(travel=false){const p=place();return `<section class="panel place-panel" id="section-place"><div class="section-kicker">${icon('pin')} MIEJSCE ${isLoad()?'ZAŁADUNKU':'ROZŁADUNKU'}</div><h3>${p.company}</h3><p class="address"><strong>${p.street}</strong><br>${p.city}</p><div class="gate-chips">${[['Brama',p.gate],['Parking',p.parking],['Magazyn',p.warehouse],['Rampa',p.ramp]].map(([l,v])=>`<div class="gate-chip"><small>${l}</small><b>${v}</b></div>`).join('')}</div><p class="arrival-instructions"><strong>Gdzie podjechać i do kogo się zgłosić</strong><br>${isLoad()?'Wjedź bramą B i zatrzymaj się na parkingu P2. W ochronie podaj nazwę ID Logistics. Odbiór w magazynie 4, rampa 04. Zgłoś się do Thomasa de Vries.':'Wjedź bramą A i zatrzymaj się na parkingu P1. Odbiorca mieści się w magazynie 3, rampa 12. Zgłoś się do Anny Kowalskiej przed rozładunkiem.'}</p><div class="contact-row"><span class="contact-avatar">${isLoad()?'TV':'AK'}</span><div class="contact-info"><strong>${p.contact}</strong><small>Magazyn · ${p.phone}</small></div><button class="contact-button" data-modal="contact" aria-label="Kontakt z osobą w magazynie">${icon('phone')}</button></div>${!travel?`<div class="yard-attachment"><div class="attachment-label"><strong>Plan terenu od zleceniodawcy</strong><span>1 materiał</span></div><button class="yard-plan" data-modal="yard" aria-label="Powiększ plan dojazdu po terenie magazynu">${yardPlan()}</button><p>Brama → parking → właściwy magazyn i rampa. Dotknij planu, aby powiększyć.</p></div>`:`<a class="primary-button travel-nav" href="${mapsLink(true)}" target="_blank" rel="noopener">${icon('nav')} Otwórz nawigację</a>`}</section>`;}
function transportPanel(){return `<section class="panel transport-panel" aria-label="Dane nadawcy i odbiorcy"><div class="transport-location"><span class="route-dot"></span><div><div class="section-kicker">ZAŁADUNEK / ${dictionary[state.language].pickup}</div><h4>ID Logistics Tilburg B.V.</h4><p>Hermesstraat 1<br>5047 TS Tilburg, Holandia</p></div></div><div class="transport-line"></div><div class="transport-location"><span class="route-dot destination"></span><div><div class="section-kicker">ROZŁADUNEK / ${dictionary[state.language].delivery}</div><h4>LogiPark Poznań</h4><p>ul. Magazynowa 18<br>62-023 Gądki, Polska</p></div></div></section>`;}
function cargoPanel(){return `<section class="panel cargo-panel"><div class="cargo-primary"><span class="cargo-symbol">${icon('box')}</span><div><h4>2 sztuki · palety EUR</h4><p>Części maszyn, w opakowaniu</p></div></div><div class="cargo-metrics"><div><span class="metric-label">Masa całkowita</span><strong class="metric-value">240 kg</strong></div><div><span class="metric-label">Wymiary / sztuka</span><strong class="metric-value">120 × 80 × 100 cm</strong></div></div><div class="reference-row"><span>Referencja załadunku</span><strong class="reference-code">REF-2026-0814<button class="copy-button" id="copy-reference" aria-label="Kopiuj numer referencyjny">${icon('doc')}</button></strong></div></section>`;}
function notesPanel(){return `<section class="panel notes-panel" id="section-notes"><p class="note-text"><strong>Obsługa ładunku</strong><br>Nie piętruj palet. Towar odbierz w oryginalnym opakowaniu. Ustaw obie palety przy prawej ścianie pojazdu i zabezpiecz pasami.</p><p class="note-text"><strong>Kontakt i dokumenty</strong><br>W razie uszkodzenia opakowania zgłoś problem przed rozpoczęciem ${genitive()}. Dokument CMR odbierz w biurze przy rampie ${place().ramp}. Upewnij się, że liczba sztuk na CMR zgadza się ze zleceniem.</p><p class="notes-source">Wszystkie uwagi do zlecenia są widoczne powyżej.</p></section>`;}
function step(index,title,content){const done=completed()[index],active=nextStep()===index;return `<section class="workflow-step ${done?'complete':active?'current':''} ${index===5?'future-step':''}" id="section-${anchors[index]}" aria-labelledby="step-title-${index}"><div class="step-heading"><span class="step-number">${done?icon('check'):index+1}</span><h4 id="step-title-${index}">${title}</h4><span class="step-status ${done?'done':''}">${done?'Gotowe':active?'Teraz':'Później'}</span></div>${content}</section>`;}
const lockedNote=text=>`<div class="locked-note">${icon('info')}${text}</div>`;
function labelRow(index){const s=current(),enabled=s.count;return `<label class="check-row ${enabled?'':'disabled'}"><input type="checkbox" data-cargo-label="${index}" ${s.labels[index]?'checked':''} ${enabled?'':'disabled'}><span>Paleta ${index+1} — ${isLoad()?'etykieta naklejona na opakowaniu':'etykieta obecna i czytelna'}</span></label>`;}
function scanRow(index,enabled){const code=current().seals[index];return `<div class="scan-row ${code?'done':''}"><span class="scan-item-icon">${icon(index===2?'doc':'box')}</span><div class="scan-info"><strong>${index===2?'QR dokumentu CMR':`QR ładunku · Paleta ${index+1}`}</strong><small>${code?esc(code):index===2?'Odrębna etykieta na dokumencie':'Etykieta fizycznie przyklejona do opakowania'}</small></div><button class="scan-button ${code?'scanned':''}" data-scan="${index}" ${enabled?'':'disabled'} aria-label="${code?'Zmień':'Skanuj'} ${index===2?'QR dokumentu CMR':'QR palety '+(index+1)}">${icon(code?'check':'qr')}${code?'Zmień':'Skanuj'}</button></div>`;}
function photoBlock(index,enabled){const photo=current().photos[index],title=index===0?'Zbliżenie ładunku':'Cała przestrzeń ładunkowa';return `<div class="photo-block"><h5><span class="photo-number">${index+1}</span>${title}</h5>${photo?`<img class="photo-preview" src="${photo.url}" alt="${title}${photo.demo?' — przykład demonstracyjny':''}"><div class="photo-toolbar"><span>${photo.demo?'Przykład w prototypie':'Podgląd w tej karcie'}</span><button data-photo="${index}">${icon('edit')} Zmień zdjęcie</button></div>`:`<button class="photo-placeholder" data-photo="${index}" ${enabled?'':'disabled'}>${icon('camera')}<strong>Zrób lub dodaj zdjęcie</strong><small>${index===0?'Ładunek wypełnia cały kadr':'Całe wnętrze pojazdu w jednym kadrze'}</small></button>`}<p class="photo-instruction">${index===0?'Pokaż dokładnie towar lub jego opakowanie. Podejdź tak blisko, aby ładunek wypełniał kadr.':'Cofnij się i pokaż całe wnętrze pojazdu, załadowany towar oraz jego umiejscowienie w przestrzeni ładunkowej.'}</p></div>`;}
function workflow(){const s=current(),done=completed();return `<div class="section-heading procedure-heading"><h3>Czynności ${genitive()}</h3><span>${done.filter(Boolean).length}/6 gotowe</span></div><p class="procedure-caption">Wykonuj kroki po kolei. Najpierw ładunek i zdjęcia, potem dokumenty CMR.</p>${step(0,'Sprawdź liczbę sztuk',`<p class="step-description">Oczekujemy <strong>2 sztuk ładunku — 2 palet.</strong> Fizycznie sprawdź ${isLoad()?'otrzymany':'dostarczany'} towar i potwierdź zgodność ze zleceniem.</p>${s.count?`<div class="inline-status">${icon('check')} Potwierdzono zgodność: 2 sztuki</div>`:`<button class="confirm-count" id="confirm-count">${icon('check')} Potwierdzam, że ${isLoad()?'otrzymałem':'dostarczam'} 2 sztuki</button>`}<button class="minor-button" data-modal="count-issue">Liczba sztuk się nie zgadza</button>${s.discrepancy?`<div class="discrepancy-notice">W podglądzie zgłoszono ${s.discrepancy} szt. Zakończenie wymaga wyjaśnienia rozbieżności.</div>`:''}`)}${step(1,isLoad()?'Naklej etykiety QR na ładunek':'Sprawdź etykiety na ładunku',`<p class="step-description">${isLoad()?'Naklej <strong>osobną, unikalną etykietę QR na każdej palecie.</strong> Umieść ją w widocznym miejscu na opakowaniu.':'Sprawdź obecność osobnej etykiety QR na każdej palecie.'}<br><strong>${isLoad()?'Nie naklejaj etykiety bezpośrednio na produkcie.':'Nie usuwaj etykiet przed odczytem.'}</strong>${isLoad()?' Dzięki temu unikniesz uszkodzenia towaru.':''}</p>${[0,1].map(labelRow).join('')}${s.count?'':lockedNote('Najpierw potwierdź liczbę sztuk.')}`)}${step(2,'Zeskanuj QR z ładunku',`<p class="step-description">Skanuj etykietę <strong>fizycznie przyklejoną do opakowania</strong> każdej palety. Każdy kod przypisz do właściwej sztuki.</p>${[0,1].map(i=>scanRow(i,done[1])).join('')}${done[1]?'':lockedNote('Najpierw potwierdź oznaczenie obu palet.')}`)}${step(3,'Zrób dwa zdjęcia ładunku',`<p class="step-description">Wykonaj zdjęcia <strong>przed odbiorem i oznaczeniem dokumentów CMR.</strong> Nie czekaj, aż magazyn przygotuje dokumenty.</p>${[0,1].map(i=>photoBlock(i,done[2])).join('')}${done[2]?'':lockedNote('Najpierw odczytaj QR obu sztuk ładunku.')}`)}${step(4,isLoad()?'Oznacz i zeskanuj QR dokumentu CMR':'Sprawdź i zeskanuj QR dokumentu CMR',`<span class="cmr-section-label">DOKUMENT — OSOBNY KOD QR</span><p class="step-description">Gdy otrzymasz CMR, ${isLoad()?'naklej na nim <strong>odrębną etykietę z unikalnym QR.</strong> Miejsce: <strong>tył ostatniej, pustej strony dokumentu CMR.</strong>':'sprawdź etykietę QR z tyłu ostatniej, pustej strony dokumentu.'} Następnie zeskanuj kod z tej etykiety.</p><label class="check-row ${done[3]?'':'disabled'}"><input id="cmr-label-confirm" type="checkbox" ${s.cmrLabel?'checked':''} ${done[3]?'':'disabled'}><span>${isLoad()?'Etykieta naklejona z tyłu ostatniej, pustej strony CMR':'Etykieta CMR sprawdzona i czytelna'}</span></label>${scanRow(2,done[3]&&s.cmrLabel)}<p class="step-compact-note">To skan kodu QR dokumentu. Pełną treść CMR zeskanujesz w kroku 6.</p>${done[3]?'':lockedNote('Najpierw dodaj oba zdjęcia ładunku.')}`)}${step(5,'Pełny skan CMR przy finalizacji',`<p class="step-description">Na etapie plombowania i finalizacji wykonaj <strong>czytelny skan wszystkich stron CMR.</strong> Skan QR przyklejonego na dokument nie zastępuje skanu jego treści.</p><div class="document-callout">${icon('doc')} Osobny etap: pełny dokument z czytelnym tekstem i podpisami.</div><button class="secondary-button" id="open-finalization" style="margin-top:13px" ${readyToFinalize()?'':'disabled'}>${icon('doc')} Przejdź do finalizacji</button>${readyToFinalize()?'':lockedNote('Dostępne po wykonaniu kroków 1–5.')}`)}`;}
function arrivalView(){return `<div class="app-content">${heading()}${placePanel()}<div class="section-heading"><h3>Dane transportu</h3><span>Nadawca → odbiorca</span></div>${transportPanel()}<div class="section-heading"><h3>Twój ładunek</h3><span>Wszystkie parametry</span></div>${cargoPanel()}<div class="section-heading"><h3>Notatki do zlecenia</h3><span>2 uwagi</span></div>${notesPanel()}${workflow()}</div>`;}
function routeMap(){return `<div class="map"><svg viewBox="0 0 390 180" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Poglądowa mapa dojazdu"><rect width="390" height="180" fill="#eff2e9"/><g fill="#e3e9db"><path d="M0 0h85v59H0zM290 0h100v68H290zM132 123h70v57h-70zM300 124h90v56h-90z"/></g><g fill="none" stroke="#fff" stroke-width="12"><path d="M-10 92 120 82 190 104 310 91 402 98M100-10v65l26 54-3 80M253-10 233 63v126M-10 160 112 135l87 20 108-13 96 9"/></g><path d="M60 87 120 82l70 22 43-5V65l50-12" fill="none" stroke="#ff6a1a" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/><circle cx="60" cy="87" r="9" fill="#515e73" stroke="white" stroke-width="3"/><circle cx="283" cy="53" r="11" fill="#ff6a1a" stroke="white" stroke-width="3"/></svg><span class="map-label">Mapa poglądowa</span></div>`;}
function travelView(){return `<div class="app-content">${heading(true)}${routeMap()}${placePanel(true)}<div class="section-heading"><h3>Dane transportu</h3></div>${transportPanel()}${cargoPanel()}<div class="section-heading"><h3>Notatki do zlecenia</h3></div>${notesPanel()}<p class="travel-info">Po dotarciu potwierdź przyjazd. Otworzysz ekran czynności ${genitive()}.</p></div>`;}
function demoDocument(page=1){return `<div class="demo-document"><div class="document-paper"><h4>CMR</h4><p>MIĘDZYNARODOWY SAMOCHODOWY LIST PRZEWOZOWY</p><p>ID Logistics Tilburg B.V. → LogiPark Poznań</p><p>REF-2026-0814 · 2 palety EUR · 240 kg</p><div class="paper-grid"></div><div class="paper-signature">${isLoad()?'Nadawca':'Odbiorca'} · str. ${page}</div></div><div class="demo-label">DOKUMENT DEMONSTRACYJNY</div></div>`;}
function finalizationView(){const s=current();return `<div class="app-content"><button class="subpage-back" data-screen="arrival">${icon('back')} Wróć do ekranu ${genitive()}</button><div class="overline">KROK 6 / PLOMBOWANIE I FINALIZACJA</div><h2 class="final-title">Pełny skan dokumentu CMR</h2><p class="final-intro">Zeskanuj <strong>wszystkie strony dokumentu</strong>, z czytelnym tekstem i podpisami. Sprawdź każdą stronę w podglądzie.</p><div class="final-link">${icon('qr')}<span>QR dokumentu już przypisany:<br><strong>${esc(s.seals[2]||'')}</strong></span></div><section class="panel document-panel">${s.pages.length?s.pages.map((p,i)=>`<div class="document-page"><h4>Strona ${i+1}<button data-remove-page="${i}" aria-label="Usuń stronę ${i+1}">${icon('close')}</button></h4>${p.demo?demoDocument(i+1):`<img class="document-image" src="${p.url}" alt="Podgląd strony ${i+1} dokumentu CMR">`}</div>`).join(''):`<button class="document-placeholder" id="add-cmr-page">${icon('camera')}<strong>Zeskanuj pierwszą stronę</strong><small>Cała strona w kadrze, bez odblasków</small></button>`}${s.pages.length?`<button class="secondary-button" id="add-cmr-page">${icon('plus')} Dodaj kolejną stronę</button>`:''}<p class="document-hints">Sprawdź: cztery rogi dokumentu, ostrość tekstu, numery i podpisy. Powtórz zdjęcie, jeśli jest rozmyte.</p></section><div class="document-assertion"><label class="check-row ${s.pages.length?'':'disabled'}"><input id="all-pages-confirm" type="checkbox" ${s.allPages?'checked':''} ${s.pages.length?'':'disabled'}><span>Potwierdzam, że dodałem wszystkie strony CMR i są czytelne.</span></label></div><p class="small-note">QR ładunku, QR CMR i pełny skan CMR zostały zapisane jako osobne czynności w tym podglądzie.</p></div>`;}
function routeView(){return `<div class="app-content"><button class="subpage-back" data-screen="${current().arrived?'arrival':'travel'}">${icon('back')} Wróć do aktualnego punktu</button><div class="overline">ZLECENIE SS/26/105/H</div><h2 class="final-title">Twoja trasa</h2><p class="final-intro">2 punkty · 2 palety EUR · 240 kg</p>${transportPanel()}<button class="secondary-button" data-route-operation="load">Otwórz punkt załadunku</button><button class="secondary-button" data-route-operation="unload" style="margin-top:10px">Otwórz punkt rozładunku</button></div>`;}
function successView(){return `<div class="app-content"><section class="panel completion-panel"><span class="success-icon">${icon('check')}</span><h2>${name()} zakończony</h2><p>${place().company}<br>Wszystkie wymagane czynności są gotowe.</p>${stepNames.map((n,i)=>`<div class="summary-line">${icon('check')}${n}<b>${i===3?'2/2':i===5?`${current().pages.length} str.`:'OK'}</b></div>`).join('')}</section><p class="small-note">Demonstracja zakończenia operacji.<br>Żadne dane nie zostały wysłane do systemu.</p></div>`;}
function actionView(){const done=completed(),n=nextStep();let text='',action='',symbol='arrow';if(state.screen==='travel'){text=`Dotarłem na ${isLoad()?'załadunek':'rozładunek'}`;action='arrive';symbol='check';}else if(state.screen==='arrival'){text=readyToFinalize()?'Przejdź do finalizacji':`Przejdź do kroku ${n+1}`;action=readyToFinalize()?'finalization':'next-step';}else if(state.screen==='finalization'){text=`Zakończ ${isLoad()?'załadunek':'rozładunek'}`;action='finish';symbol='check';}else if(state.screen==='success'){text=isLoad()?'Jedź na rozładunek':'Wróć do podglądu';action='next-point';symbol='route';}else{text='Wróć do aktualnego punktu';action='now';symbol='back';}return `${state.screen==='arrival'||state.screen==='finalization'?`<div class="action-progress"><span>${state.screen==='finalization'?'Sprawdź kompletność dokumentu':`Następny krok: ${stepNames[n]}`}</span><b>${done.filter(Boolean).length}/6</b></div>`:''}<button class="primary-button" id="main-action" data-action="${action}" ${action==='finish'&&!done.every(Boolean)?'disabled':''}>${icon(symbol)}${text}</button>${state.screen==='finalization'&&!done.every(Boolean)?`<p class="action-caption">Dodaj skan i potwierdź kompletność wszystkich stron.</p>`:''}`;}
function designNotes(){const done=completed();return `<h2>${state.screen==='travel'?'Najpierw dojazd.<br>Potem operacja.':'Jasne dane.<br>Prosta kolejność.'}</h2><p class="note-description">Firma, rampa, ładunek i wszystkie notatki są na jednym ekranie. Kierowca przewija i przechodzi przez kolejne czynności.</p><div class="design-progress"><div class="design-progress-title">PROCEDURA ${name().toUpperCase()}<span>${done.filter(Boolean).length}/6</span></div>${stepNames.map((n,i)=>`<div class="design-step ${done[i]?'done':nextStep()===i?'current':''}"><span class="design-step-num">${done[i]?icon('check'):String(i+1).padStart(2,'0')}</span><span>${n}</span></div>`).join('')}</div>`;}
function updateSidebar(){$$('[data-scroll]', $('.screen-list')).forEach(b=>b.classList.toggle('active',state.screen==='arrival'&&b.dataset.scroll===state.anchor));$$('[data-screen]', $('.screen-list')).forEach(b=>b.classList.toggle('active',b.dataset.screen===state.screen));}
function render(){const scroll=$('#app-scroll').scrollTop;const views={arrival:arrivalView,travel:travelView,finalization:finalizationView,route:routeView,success:successView};$('#app').innerHTML=views[state.screen]();$('#app-action').innerHTML=actionView();$('#design-context').innerHTML=designNotes();$('#preview-label').textContent=`${name().toUpperCase()} / ${state.screen==='travel'?'W DRODZE':state.screen==='finalization'?'FINALIZACJA':state.screen==='success'?'ZAKOŃCZONE':'NA MIEJSCU'}`;$$('[data-operation]').forEach(b=>{b.classList.toggle('active',b.dataset.operation===state.operation);b.setAttribute('aria-pressed',String(b.dataset.operation===state.operation));});$('#mobile-screen').value=['arrival','travel','finalization'].includes(state.screen)?state.screen:'arrival';$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===(state.screen==='route'?'route':'now')));updateSidebar();bindView();$('#app-scroll').scrollTop=scroll;}
function bindView(){
  $$('[data-modal]',$('#app')).forEach(b=>b.onclick=()=>openModal(b.dataset.modal));
  $$('[data-screen]',$('#app')).forEach(b=>b.onclick=()=>go(b.dataset.screen));
  $$('[data-route-operation]').forEach(b=>b.onclick=()=>switchOperation(b.dataset.routeOperation,current().arrived?'arrival':'travel'));
  $$('[data-scan]').forEach(b=>b.onclick=()=>openModal('scan',Number(b.dataset.scan)));
  $$('[data-photo]').forEach(b=>b.onclick=()=>openModal('photo',Number(b.dataset.photo)));
  $$('[data-cargo-label]').forEach(input=>input.onchange=()=>{const i=Number(input.dataset.cargoLabel);current().labels[i]=input.checked;if(!input.checked){current().seals[i]=null;clearAfter(1);}render();});
  if($('#confirm-count'))$('#confirm-count').onclick=()=>{current().count=true;current().discrepancy=null;render();toast('Potwierdzono 2 sztuki ładunku. Oznacz teraz obie palety.');};
  if($('#cmr-label-confirm'))$('#cmr-label-confirm').onchange=e=>{current().cmrLabel=e.target.checked;if(!e.target.checked){current().seals[2]=null;clearAfter(4);}render();};
  if($('#open-finalization'))$('#open-finalization').onclick=()=>go('finalization');
  if($('#add-cmr-page'))$('#add-cmr-page').onclick=()=>openModal('document');
  if($('#all-pages-confirm'))$('#all-pages-confirm').onchange=e=>{current().allPages=e.target.checked;render();};
  $$('[data-remove-page]').forEach(b=>b.onclick=()=>{const removed=current().pages.splice(Number(b.dataset.removePage),1)[0];revoke(removed);current().allPages=false;render();});
  if($('#language-select'))$('#language-select').onchange=e=>{state.language=e.target.value;state.manualLanguage=true;render();};
  if($('#copy-reference'))$('#copy-reference').onclick=async()=>{try{await navigator.clipboard.writeText('REF-2026-0814');toast('Numer referencyjny skopiowany.');}catch{openModal('copy');}};
  $('#main-action').onclick=()=>{const action=$('#main-action').dataset.action;if(action==='arrive'){current().arrived=true;go('arrival');}if(action==='next-step')scrollToSection(anchors[nextStep()]);if(action==='finalization')go('finalization');if(action==='finish'&&completed().every(Boolean))openModal('finish');if(action==='now')go(current().arrived?'arrival':'travel');if(action==='next-point'){if(isLoad())switchOperation('unload','travel');else go('arrival');}};
}
function demoPhoto(index){const svg=index===0?`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 260"><rect width="500" height="260" fill="#e1e5df"/><rect x="26" y="12" width="449" height="225" rx="4" fill="#c8aa85"/><path d="M26 85h449M26 162h449M249 12v225" stroke="#ad906a" stroke-width="2"/><path d="M162 12v225M398 12v225" stroke="#627568" stroke-width="15"/><path d="M26 41l449 17M26 117l449 19M26 195l449 17" stroke="#ffffff44" stroke-width="3"/><g transform="translate(175 33)"><rect width="40" height="43" rx="3" fill="#fffdfa"/><g fill="#3b453a"><path d="M5 5h9v9H5zM25 5h9v9h-9zM5 25h9v9H5zM18 7h3v9h-3zM17 21h8v3h-8zM26 26h8v8h-8z"/></g></g><rect y="235" width="500" height="25" fill="#67766c"/><text x="250" y="251" text-anchor="middle" font-family="Arial" font-size="8" fill="white">ZDJĘCIE DEMONSTRACYJNE — ŁADUNEK Z BLISKA</text></svg>`:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 260"><rect width="500" height="260" fill="#cbd0cb"/><path d="M40 0 160 45h180L460 0" fill="#e1e4df"/><path d="m40 0 120 45v125L40 243zM460 0 340 45v125l120 73" fill="#d0d8ce"/><path d="M160 45h180v125H160Z" fill="#c1cbbd"/><path d="M40 243 160 170h180l120 73" fill="#9fae9b"/><g fill="none" stroke="#adbba6" stroke-width="4"><path d="M72 15v207M114 32v165M428 15v207M386 32v165M40 117l120-16M340 101l120 16M65 237l102-63M434 237l-102-63"/></g><g fill="#c8ad87" stroke="#ae916b"><rect x="197" y="104" width="127" height="77"/><path d="M197 141h127M260 104v77"/><rect x="274" y="171" width="133" height="56"/><path d="M274 198h133M340 171v56"/></g><path d="M225 104v77M303 104v77M301 171v56M385 171v56" stroke="#627966" stroke-width="8"/><rect x="189" y="181" width="143" height="8" fill="#a08b67"/><rect x="267" y="227" width="146" height="8" fill="#a08b67"/><rect x="242" y="113" width="13" height="15" fill="white"/><path d="M242 115h7v7h-7M246 120h7v6" stroke="#414b3d" stroke-width="2"/><rect y="245" width="500" height="15" fill="#5f7161"/><text x="250" y="255" text-anchor="middle" font-family="Arial" font-size="7" fill="white">ZDJĘCIE DEMONSTRACYJNE — CAŁA PRZESTRZEŃ ŁADUNKOWA</text></svg>`;return'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
function openModal(type,target){focusBeforeModal=document.activeElement;state.modal={type,target};let title='',body='';
  if(type==='photo'){if(!completed()[2])return closeModal();title=target===0?'Zbliżenie ładunku':'Cała przestrzeń ładunkowa';body=`<p>${target===0?'Ładunek powinien wypełniać cały kadr. Pokaż dokładnie towar lub opakowanie.':'Obejmij całe wnętrze pojazdu. Pokaż załadowany towar i jego pozycję w przestrzeni ładunkowej.'}</p><img class="photo-preview" src="${demoPhoto(target)}" alt="Ilustracja przykładowego kadru"><button class="primary-button" id="choose-file">${icon('camera')} Aparat lub zdjęcie z urządzenia</button><button class="secondary-button" id="use-demo">Wypróbuj na zdjęciu przykładowym</button><p class="small-note">Prototyp: plik pozostanie tylko w tej karcie, bez wysyłania do systemu.</p>`;}
  if(type==='scan'){const allowed=target===2?completed()[3]&&current().cmrLabel:completed()[1];if(!allowed)return closeModal();title=target===2?'QR dokumentu CMR':`QR ładunku · Paleta ${target+1}`;body=`<p>${target===2?'Zeskanuj odrębną etykietę z tyłu ostatniej, pustej strony CMR. Ten odczyt nie jest skanem treści dokumentu.':'Zeskanuj etykietę fizycznie naklejoną na opakowaniu tej palety.'}</p><div class="scan-camera"><span class="scan-guide">${icon('qr')}</span><span class="demo-watermark">Skaner demonstracyjny — odczyt symulowany</span></div><button class="primary-button" id="simulate-scan">${icon('qr')} Symuluj odczyt QR</button><label for="qr-code" class="field-label">Lub wpisz kod z etykiety</label><input id="qr-code" class="text-input" autocomplete="off" maxlength="64" placeholder="${target===2?'SS-260814-CMR':`SS-260814-0${target+1}`}"><p id="qr-error" class="field-error" role="alert"></p><button class="secondary-button" id="manual-scan">Zatwierdź wpisany kod</button>`;}
  if(type==='document'){if(!readyToFinalize())return closeModal();title='Skan strony CMR';body=`<p>Sfotografuj całą stronę. Sprawdź tekst, numery i podpisy. Kolejne strony dodasz osobno.</p>${demoDocument(current().pages.length+1)}<button class="primary-button" id="choose-file">${icon('camera')} Aparat lub skan z urządzenia</button><button class="secondary-button" id="use-demo">Dodaj przykładową stronę</button><p class="small-note">Prototyp nie wykonuje kadrowania ani OCR. Plik pozostaje w tej karcie przeglądarki.</p>`;}
  if(type==='yard'){title='Dojazd po terenie magazynu';body=`<div class="yard-modal">${yardPlan()}</div><p><strong>${place().company}</strong><br>${place().street}, ${place().city}</p><p>Brama ${place().gate} → parking ${place().parking} → magazyn ${place().warehouse} → rampa ${place().ramp}.</p><p class="small-note">Plan poglądowy jako przykład materiału od zleceniodawcy.</p>`;}
  if(type==='contact'){title='Kontakt w magazynie';body=`<p><strong>${place().contact}</strong><br>${place().company}<br>${place().phone}</p><p>Referencja do rozmowy:<br><strong>REF-2026-0814</strong></p><button class="primary-button" id="demo-call">${icon('phone')} Podgląd połączenia</button><p class="small-note">Numer jest przykładowy. W aplikacji przycisk otworzy telefon.</p>`;}
  if(type==='copy'){title='Numer referencyjny';body=`<p>Zaznacz i skopiuj numer:</p><input class="text-input" value="REF-2026-0814" readonly aria-label="Numer referencyjny">`;}
  if(type==='count-issue'){title='Niezgodna liczba sztuk';body=`<p>Zlecenie przewiduje <strong>2 sztuki</strong>. Nie potwierdzaj zgodności, jeśli liczba fizycznie otrzymanych sztuk jest inna.</p><label class="field-label" for="actual-count">Ile sztuk znajduje się na miejscu?</label><input class="text-input" id="actual-count" type="number" min="0" max="999" step="1" placeholder="np. 1"><p id="count-error" class="field-error" role="alert"></p><button class="primary-button" id="report-count">Zapisz rozbieżność w podglądzie</button><p class="small-note">Prototyp nie wysyła zgłoszenia do spedytora.</p>`;}
  if(type==='help'){title='Pomoc przy zleceniu';body=`<p>SS/26/105/H · ${place().company}</p><div class="help-options"><button id="help-contact">${icon('phone')} Kontakt z magazynem</button><button id="help-dispatch">${icon('help')} Kontakt ze spedytorem</button><button id="help-count">${icon('box')} Niezgodna liczba sztuk</button></div>`;}
  if(type==='finish'){if(!completed().every(Boolean))return closeModal();title=`Zakończyć ${isLoad()?'załadunek':'rozładunek'}?`;body=`<p>Sprawdź ostatni raz czytelność materiałów. Wszystkie sześć kroków jest uzupełnione.</p><div class="summary-line">${icon('check')} 2 sztuki potwierdzone, 2 etykiety QR <b>OK</b></div><div class="summary-line">${icon('check')} Dwa wymagane zdjęcia ładunku <b>2/2</b></div><div class="summary-line">${icon('check')} Odrębny QR na dokumencie CMR <b>OK</b></div><div class="summary-line">${icon('check')} Pełny skan CMR, wszystkie strony <b>${current().pages.length} str.</b></div><button class="primary-button" id="confirm-finish">${icon('check')} Tak, zakończ ${isLoad()?'załadunek':'rozładunek'}</button><p class="small-note">Demonstracja: nie zmieniamy rzeczywistego zlecenia.</p>`;}
  if(type==='reset'){title='Zresetować podgląd?';body=`<p>Usuniesz postęp oraz wybrane pliki z tej demonstracji i wrócisz do ekranu załadunku.</p><button class="primary-button" id="confirm-reset">Zresetuj prototyp</button>`;}
  $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal-sheet" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-handle"></div><div class="modal-title"><h3 id="modal-title">${title}</h3><button class="icon-button" id="close-modal" aria-label="Zamknij">${icon('close')}</button></div>${body}</section></div>`;
  $('#close-modal').onclick=()=>closeModal();$('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal();};
  if($('#choose-file'))$('#choose-file').onclick=()=>{uploadTarget={operation:state.operation,kind:type==='document'?'document':'photo',target};$('#file-input').value='';$('#file-input').click();};
  if($('#use-demo'))$('#use-demo').onclick=()=>{if(type==='document'){current().pages.push({demo:true});current().allPages=false;}else{revoke(current().photos[target]);current().photos[target]={demo:true,url:demoPhoto(target)};}closeModal(false);render();toast(type==='document'?'Dodano przykładową stronę CMR.':'Dodano przykładowe zdjęcie.');};
  if($('#simulate-scan'))$('#simulate-scan').onclick=()=>saveQR(target,(!isLoad()&&state.operations.load.seals[target])||(target===2?'SS-260814-CMR':`SS-260814-0${target+1}`));
  if($('#manual-scan'))$('#manual-scan').onclick=()=>saveQR(target,$('#qr-code').value);
  if($('#qr-code'))$('#qr-code').onkeydown=e=>{if(e.key==='Enter')saveQR(target,e.target.value);};
  if($('#report-count'))$('#report-count').onclick=()=>{const raw=$('#actual-count').value,n=Number(raw);if(raw===''||!Number.isInteger(n)||n<0||n>999){$('#count-error').textContent='Wpisz liczbę całkowitą od 0 do 999.';return;}if(n===2){$('#count-error').textContent='To liczba zgodna ze zleceniem. Wróć i potwierdź 2 sztuki.';return;}const s=current();s.count=false;s.labels=[false,false];s.seals=[null,null,null];clearAfter(0);s.discrepancy=n;closeModal(false);render();toast('Zapisano rozbieżność w podglądzie. Skontaktuj się ze spedytorem.');};
  if($('#demo-call'))$('#demo-call').onclick=()=>{closeModal();toast('Podgląd: połączenie z osobą kontaktową.');};
  if($('#help-contact'))$('#help-contact').onclick=()=>openModal('contact');
  if($('#help-count'))$('#help-count').onclick=()=>openModal('count-issue');
  if($('#help-dispatch'))$('#help-dispatch').onclick=()=>{closeModal();toast('Podgląd: kontakt ze spedytorem prowadzącym zlecenie.');};
  if($('#confirm-finish'))$('#confirm-finish').onclick=()=>{current().finished=true;go('success');};
  if($('#confirm-reset'))$('#confirm-reset').onclick=()=>reset();
  $('.modal-sheet').focus();
}
function saveQR(index,raw){const code=raw.trim().toUpperCase();if(!/^[A-Z0-9][A-Z0-9._/-]{3,63}$/.test(code)){$('#qr-error').textContent='Wpisz kod z etykiety (minimum 4 znaki, bez spacji).';return;}const duplicate=Object.values(state.operations).some(op=>op.seals.some((c,i)=>c===code&&i!==index));if(duplicate){$('#qr-error').textContent='Ten kod jest już przypisany do innej sztuki lub dokumentu. Użyj odrębnej, unikalnej etykiety.';return;}if(!isLoad()){const expected=state.operations.load.seals[index]||(index===2?'SS-260814-CMR':`SS-260814-0${index+1}`);if(code!==expected){$('#qr-error').textContent=`Kod nie pasuje do tej pozycji. W przykładzie oczekujemy: ${expected}.`;return;}}if(current().seals[index]&&current().seals[index]!==code)clearAfter(index===2?4:1);current().seals[index]=code;closeModal(false);render();toast(index===2?'QR dokumentu CMR przypisany. Pełny skan dodasz przy finalizacji.':'QR przypisany do właściwej sztuki ładunku.');}
function closeModal(restore=true){$('#modal-root').innerHTML='';state.modal=null;if(restore&&focusBeforeModal?.isConnected)focusBeforeModal.focus();}
function switchOperation(operation,screen='arrival'){state.operation=operation;if(!state.manualLanguage)state.language=operation==='load'?'en':'pl';go(screen);}
function reset(){Object.values(state.operations).forEach(op=>[...op.photos,...op.pages].forEach(revoke));state.operations={load:fresh(),unload:fresh()};state.operation='load';state.language='en';state.manualLanguage=false;go('arrival');toast('Podgląd został zresetowany.');}
$('#file-input').onchange=e=>{const file=e.target.files[0];if(!file||!uploadTarget)return;if(!file.type.startsWith('image/')){toast('Wybierz zdjęcie JPG, PNG lub WebP.');return;}if(file.size>20*1024*1024){toast('Wybierz plik do 20 MB.');return;}const url=URL.createObjectURL(file),img=new Image(),target={...uploadTarget};img.onload=()=>{const op=state.operations[target.operation],data={url,demo:false};if(target.kind==='document'){op.pages.push(data);op.allPages=false;}else{revoke(op.photos[target.target]);op.photos[target.target]=data;}closeModal(false);render();toast(target.kind==='document'?'Dodano podgląd strony CMR.':'Dodano podgląd zdjęcia.');};img.onerror=()=>{URL.revokeObjectURL(url);toast('Nie udało się odczytać zdjęcia. Wybierz JPG, PNG lub WebP.');};img.src=url;};
$$('[data-operation]').forEach(b=>b.onclick=()=>switchOperation(b.dataset.operation));
$$('[data-screen]',$('.screen-list')).forEach(b=>b.onclick=()=>go(b.dataset.screen));
$$('[data-scroll]',$('.screen-list')).forEach(b=>b.onclick=()=>scrollToSection(b.dataset.scroll));
$('#mobile-screen').onchange=e=>{const selected=e.target.value;go(selected);$('#mobile-screen').value=['arrival','travel','finalization'].includes(state.screen)?state.screen:'arrival';};
$$('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='now')go(current().arrived?(current().finished?'success':'arrival'):'travel');if(b.dataset.nav==='route')go('route');if(b.dataset.nav==='help')openModal('help');});
$('#reset').onclick=()=>openModal('reset');
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const list=$$('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]',$('.modal-sheet'));const first=list[0],last=list.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal-sheet'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal-sheet'))){e.preventDefault();first?.focus();}}});
render();
